protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    // Keep "Discriminator" property name for compatibility with existing documents
    // (EF Core 9 defaults to "$type")
    modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

    // Keep discriminator in id (e.g. "Blog|1") for compatibility with existing documents
    // (EF Core 9 defaults to key-only ids)
    modelBuilder.Entity<Blog>().HasRootDiscriminatorInJsonId(true);

    // HasIndex removed — Cosmos DB throws at startup in EF Core 9.
    // Manage indexing via Azure Portal or Bicep instead.
}

